Body:
currenlty i use this snippet ( add it to `.bashrc` or `.zshrc` file in home directory)

```sh
oc-sessions() {
  (
    echo "ID|TITLE|DIRECTORY"
    sqlite3 ~/.local/share/opencode/opencode.db \
      "SELECT id || '|' || title || '|' || directory FROM session" |
    sed -E 's#^([^|]*\|[^|]*\|).*/([^/]*/[^/]*/[^/]*)$#\1\2#'
  ) | awk -F'|' '
  BEGIN {
      cyan="\033[96m"
      reset="\033[0m"
  }
  NR==1 {
      printf "%-32s %-45s %s\n", $1, $2, $3
      printf "%-32s %-45s %s\n", "--------------------------------", "---------------------------------------------", "----------------------------------------"
      next
  }
  {
      printf "%-32s %s%-45s%s %s\n", $1, cyan, $2, reset, $3
  }'
}
```
